s="term-action" data-bs-toggle="modal" data-bs-target="#termFormModal" data-item="{{base64_encode(json_encode($d))}}" onclick="openTerm(this.dataset.item)" title="Edit">{!!$i['edit']!!}</button><button class="term-action" data-bs-toggle="modal" data-bs-target="#termStatusModal" data-item="{{base64_encode(json_encode($d))}}" onclick="statusTerm(this.dataset.item)" title="Status">{!!$i['status']!!}</button><form method="POST" action="{{route('terminations-destroy',$t)}}" class="term-delete" data-name="{{$t->employee?->name}}">@csrf @method('DELETE')<button class="term-action" title="Delete">{!!$i['delete']!!}</button></form></div></td></tr>@empty<tr><td colspan="8" class="text-center py-10 text-muted">No terminations found.</td></tr>@endforelse</tbody></table></div><div class="d-flex justify-content-between align-items-center p-5"><span class="text-muted">Showing {{$terminations->firstItem()??0}} to {{$terminations->lastItem()??0}} of {{$terminations->total()}} results</span>{{$terminations->links('pagination::bootstrap-4')}}</div></div></div>
