<div class="modal fade term-modal" id="termStatusModal"><div class="modal-dialog modal-dialog-centered modal-sm"><div class="modal-content"><form id="termStatusForm" method="POST">@csrf @method('PATCH')<div class="modal-header"><h2 class="fs-4 mb-0">Change Termination Status</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-5"><label class="form-label required">Status</label><select class="form-select" name="status"><option>Planned</option><option>In Progress</option><option>Completed</option></select></div><label class="mb-5"><input type="hidden" name="exit_interview_conducted" value="0"><input type="checkbox" name="exit_interview_conducted" value="1"> Exit Interview Conducted</label><div class="mb-5"><label class="form-label">Exit Interview Date</label><input class="form-control" type="date" name="exit_interview_date"></div><div><label class="form-label">Exit Feedback</label><textarea class="form-control" rows="3" name="exit_feedback"></textarea></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success">Save</button></div></form></div></div></div>
<script>const ts=@json(route('terminations-store')),tu=@json(route('terminations-update','__ID__')),tx=@json(route('terminations-status','__ID__'));function td(x){return x?JSON.parse(atob(x)):{} }function openTerm(x){let d=td(x),f=termForm;f.reset();f.action=ts;termMethod.innerHTML='';termTitle.textContent=d.id?'Edit Termination':'Add New Termination';['employee_id','termination_type_id','notice_date','termination_date','notice_period','reason','description'].forEach(k=>f.elements[k].value=d[k]||'');if(d.id){f.action=tu.replace('__ID__',d.id);termMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function viewTerm(x){let d=td(x),m=termViewModal;m.querySelector('[data-tv=avatar]').src=d.avatar;m.querySelector('[data-tv=employee]').textContent=d.employee_name;let b=m.querySelector('[data-tv=status]');b.textContent=d.status;b.className='ms-auto term-badge term-'+d.status.toLowerCase().replace(' ','-');let v={type:d.type,notice:d.notice_period,notice_date:d.notice_date,date:d.termination_date,reason:d.reason,description:d.description,feedback:d.exit_feedback};Object.keys(v).forEach(k=>m.querySelector('[data-tv='+k+']').textContent=v[k]||'—');m.querySelector('[data-tv=document]').innerHTML=d.document_url?(/\.(png|jpe?g)$/i.test(d.document_path)?'<a target="_blank" href="'+d.document_url+'"><img class="term-preview" src="'+d.document_url+'"></a>':'<a target="_blank" href="'+d.document_url+'">View document</a>'):'—'}function statusTerm(x){let d=td(x),f=termStatusForm;f.action=tx.replace('__ID__',d.id);f.elements.status.value=d.status;f.querySelector('[type=checkbox]').checked=!!d.exit_interview_conducted;f.elements.exit_interview_date.value=d.exit_interview_date||'';f.elements.exit_feedback.value=d.exit_feedback||''}document.addEventListener('DOMContentLoaded',()=>{termForm.onsubmit=e=>{termForm.querySelectorAll('.term-error').forEach(x=>x.remove());let first;Object.entries({employee_id:'Employee',termination_type_id:'Termination Type',notice_date:'Notice Date',termination_date:'Termination Date',reason:'Reason'}).forEach(([k,n])=>{let a=termForm.elements[k];if(!a.value){a.insertAdjacentHTML('afterend','<div class="term-error">'+n+' is required</div>');first=first||a}});if(first){e.preventDefault();first.focus()}};document.querySelectorAll('.term-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete termination?',text:'Delete '+f.dataset.name+' termination? This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})})</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
 var statusClose=document.querySelector('#termStatusModal .btn-close');if(statusClose)statusClose.type='button';
 var body=document.querySelector('#termFormModal .modal-body');
 body.insertAdjacentHTML('beforeend','<div id="termEditExtra" style="display:none"><input type="hidden" name="remove_document" value="0"><div id="termExistingDocument" class="mt-4 mb-5"></div><div class="mb-5"><label class="form-label required">Status</label><select class="form-select" name="status"><option>Planned</option><option>In Progress</option><option>Completed</option></select></div><label class="d-block mb-5"><input type="hidden" name="exit_interview_conducted" value="0"><input type="checkbox" name="exit_interview_conducted" value="1"> &nbsp; Exit Interview Conducted</label><div class="mb-5"><label class="form-label">Exit Interview Date</label><input class="form-control" type="date" name="exit_interview_date"></div><div><label class="form-label">Exit Feedback</label><textarea class="form-control" rows="3" name="exit_feedback" placeholder="Employee feedback during exit interview..."></textarea></div></div>');
 var original=window.openTerm;
 window.openTerm=function(encoded){original(encoded);var d=td(encoded),f=document.getElementById('termForm'),extra=document.getElementById('termEditExtra'),doc=document.getElementById('termExistingDocument');extra.style.display=d.id?'block':'none';f.elements.remove_document.value='0';f.elements.status.value=d.status||'Planned';f.querySelector('#termEditExtra input[type=checkbox]').checked=!!d.exit_interview_conducted;f.elements.exit_interview_date.value=d.exit_interview_date||'';f.elements.exit_feedback.value=d.exit_feedback||'';doc.innerHTML='';if(d.id&&d.document_url){var name=(d.document_path||'Document').split('/').pop(),isImage=/\.(png|jpe?g|webp)$/i.test(name);doc.innerHTML='<label class="form-label">Current Document</label><div class="d-flex align-items-center gap-3"><a class="form-control text-truncate" target="_blank" href="'+d.document_url+'">'+name+'</a><button class="btn btn-light-danger" type="button" id="termRemoveDocument">×</button></div>'+(isImage?'<a target="_blank" href="'+d.document_url+'"><img class="term-preview mt-3" src="'+d.document_url+'"></a>':'');document.getElementById('termRemoveDocument').onclick=function(){f.elements.remove_document.value='1';doc.style.display='none'}}doc.style.display='block'};
});
</script>
